#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "lu.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Original lower-triangular construction. */
  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite.
     Not necessary for LU, but using same code as cholesky. */
  int r, s, t;

  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Use local restrict-qualified pointers to help the compiler
     with alias analysis and address arithmetic. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict B_)[n] = POLYBENCH_ARRAY(B);

  /* Initialize B to zero.  Using an explicit loop keeps semantics clear
     for arbitrary DATA_TYPE. */
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      B_[r][s] = (DATA_TYPE)0;

  /* Compute B = A * A^T via rank-1 updates:
       B[r][s] += A[r][t] * A[s][t]
     The loop structure is kept identical to the original to preserve
     numerical behavior, but we cache A[r][t] in a scalar to reduce
     memory traffic. */
  for (t = 0; t < n; ++t)
    for (r = 0; r < n; ++r)
      {
        DATA_TYPE Art = A_[r][t];
        for (s = 0; s < n; ++s)
          B_[r][s] += Art * A_[s][t];
      }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      A_[r][s] = B_[r][s];

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_lu[[gnu::flatten, gnu::noinline]](int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Local restrict-qualified view of A to help optimization. */
  DATA_TYPE (*restrict A_)[n] = A;

#pragma scop
  for (i = 0; i < _PB_N; i++) {

    /* Cache the current row pointer to reduce address arithmetic and
       improve data locality.  The restrict qualifier tells the
       compiler that Ai does not alias any other pointer in this
       scope, enabling better vectorization and scheduling. */
    DATA_TYPE *restrict Ai = A_[i];

    /* Compute the L part: A[i][j] for j < i.
       We rewrite the inner loop to accumulate into a scalar 'sum'
       instead of repeatedly updating A[i][j] in memory.  This exposes
       a classic dot-product pattern and lets the compiler keep the
       running value in a register. */
    for (j = 0; j < i; j++) {
      DATA_TYPE sum = Ai[j];
      for (k = 0; k < j; k++) {
        sum -= Ai[k] * A_[k][j];
      }
      sum /= A_[j][j];
      Ai[j] = sum;
    }

    /* Compute/update the U part: A[i][j] for j >= i.
       Original code:

         for (j = i; j < _PB_N; j++)
           for (k = 0; k < i; k++)
             A[i][j] -= A[i][k] * A[k][j];

       We reorder the loops to k-outer / j-inner:

         for (k = 0; k < i; k++)
           for (j = i; j < _PB_N; j++)
             A[i][j] -= A[i][k] * A[k][j];

       For each fixed j, the sequence of operations over k is unchanged
       (k still goes from 0 to i-1 in ascending order), and different
       j indices are completely independent.  Therefore, each A[i][j]
       sees the same sequence of floating-point operations as in the
       original code, preserving numerical semantics while improving
       cache locality (row-wise accesses) and enabling vectorization
       of the inner j-loop. */
    for (k = 0; k < i; k++) {
      DATA_TYPE Aik = Ai[k];
      DATA_TYPE *restrict Ak = A_[k];

      /* Encourage SIMD vectorization over columns j.
         This pragma is ignored by compilers that do not support
         OpenMP, so portability is preserved. */
#pragma omp simd
      for (j = i; j < _PB_N; j++) {
        Ai[j] -= Aik * Ak[j];
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_lu (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
