#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "lu.h"

#ifdef _OPENMP
/* OpenMP is only used via pragmas; this header is optional but useful
 * if the program is compiled with -fopenmp and wants to query the
 * runtime. No OpenMP API calls are made in this file. */
#include <omp.h>
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Precompute 1/n once to avoid repeated division/modulo.
     Original formula:
       A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
     For 0 <= j < n, we have (-j % n) == -j in C, so:
       A[i][j] = - (DATA_TYPE)j / n + 1
               = 1 - (DATA_TYPE)j / n.
   */
  const DATA_TYPE fn    = (DATA_TYPE)n;
  const DATA_TYPE inv_n = (DATA_TYPE)1.0 / fn;

  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)1.0 - ((DATA_TYPE)j) * inv_n;
      for (j = i+1; j < n; j++) {
	A[i][j] = (DATA_TYPE)0;
      }
      A[i][i] = (DATA_TYPE)1.0;
    }

  /* Make the matrix positive semi-definite.
     We compute B = A * A^T and then copy B back into A.
     This is mathematically identical to the original code but uses a
     loop order that improves data locality and exposes parallelism.
   */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Each iteration of the outer 'r' loop touches only row r of B, so
     it can be parallelized safely. The inner loops keep 's' as the
     innermost index to write B[r][s] in row-major order. */
#if defined(_OPENMP)
#pragma omp parallel for private(s,t)
#endif
  for (r = 0; r < n; ++r)
    {
      /* Initialize row r of B to zero. */
      for (s = 0; s < n; ++s)
	(POLYBENCH_ARRAY(B))[r][s] = (DATA_TYPE)0;

      /* Accumulate B[r][s] += sum_t A[r][t] * A[s][t].
         For each fixed (r,s), 't' still runs from 0 to n-1 in order,
         exactly as in the original implementation, so the per-element
         accumulation order is preserved. */
      for (t = 0; t < n; ++t)
	{
	  const DATA_TYPE art = A[r][t];
	  for (s = 0; s < n; ++s)
	    (POLYBENCH_ARRAY(B))[r][s] += art * A[s][t];
	}
    }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      A[r][s] = (POLYBENCH_ARRAY(B))[r][s];

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_lu[[gnu::flatten, gnu::noinline]](int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Use PolyBench-provided loop bound macro; this may differ from the
     raw 'n' parameter in some configurations (e.g., for validation or
     reduced problem sizes). */
  const int n_ = _PB_N;

#pragma scop
  for (i = 0; i < n_; i++) {

    /* Compute the strictly lower-triangular part of row i (L factors).
       For j < i:
         A[i][j] = ( A[i][j] - sum_{k=0..j-1} A[i][k] * A[k][j] ) / A[j][j]
       We keep a scalar accumulator 'sum' to minimize memory traffic
       and allow the compiler to optimize the inner dot product. */
    for (j = 0; j < i; j++) {
      DATA_TYPE sum = A[i][j];

      /* Dot product L(i,0..j-1) * U(0..j-1,j). */
      for (k = 0; k < j; k++) {
	sum -= A[i][k] * A[k][j];
      }

      /* Divide by the pivot on the diagonal of U. */
      sum /= A[j][j];
      A[i][j] = sum;
    }

    /* Compute the upper-triangular part of row i (U factors).
       For j >= i:
         A[i][j] = A[i][j] - sum_{k=0..i-1} A[i][k] * A[k][j]
       Each column j in this loop is independent for a fixed i, so
       we can parallelize this loop across columns when OpenMP is
       enabled. */
#if defined(_OPENMP)
#pragma omp parallel for private(k) schedule(static)
#endif
    for (j = i; j < n_; j++) {
      DATA_TYPE sum = A[i][j];

      /* Dot product L(i,0..i-1) * U(0..i-1,j). */
      for (k = 0; k < i; k++) {
	sum -= A[i][k] * A[k][j];
      }

      A[i][j] = sum;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_lu (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
