 *
 * Optimizations:
 *  - Avoid the (% n) operation in the initialization formula; for 0 <= j < n,
 *    (-j % n) == -j, so we can use a simpler arithmetic expression.
 *  - Use a precomputed 1/n to reduce the number of divisions.
 *  - Parallelize row-wise initialization with OpenMP (optional; pragmas are
 *    ignored if compiled without OpenMP support).
 *  - In the positive semi-definite transformation, compute B = A * A^T using
 *    a more cache-friendly order, exploit symmetry (compute only half of B
 *    and mirror it), and avoid the explicit zero-initialization of B.
 *  - Copy B back into A row-by-row using memcpy to encourage efficient
 *    memory transfers.
 *
 * All transformations preserve the mathematical result of the original code.
 */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Precompute reciprocal of n to reduce divisions in the first initialization
   * loop. This changes the way floating-point rounding is performed compared
   * to repeated divisions, but the mathematical formula remains:
   *   A[i][j] = 1 - j/n
   * which is equivalent to the original
   *   A[i][j] = (DATA_TYPE)(-j % n) / n + 1
   * for all 0 <= j < n because (-j % n) == -j in that range.
   */
  const DATA_TYPE inv_n = (DATA_TYPE)1.0 / (DATA_TYPE)n;

  /* Initialize A as in the original code, but with the simplified formula and
   * optional parallelization across rows.
   */
  #pragma omp parallel for private(j) schedule(static)
  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
        A[i][j] = (DATA_TYPE)1.0 - ((DATA_TYPE)j) * inv_n;

      for (j = i+1; j < n; j++)
	A[i][j] = (DATA_TYPE)0.0;

      A[i][i] = (DATA_TYPE)1.0;
    }

  /* Make the matrix positive semi-definite.
   * We compute B = A * A^T and then copy B back into A.
   *
   * Optimizations compared to the original:
   *   - We compute B element-wise as an inner-product:
   *       B[r][s] = sum_t A[r][t] * A[s][t]
   *     instead of incrementally adding contributions across t in a separate
   *     loop nest. For each (r, s), the accumulation across t is still in
   *     increasing order, so the arithmetic is equivalent, but we keep the
   *     partial sum in a scalar register instead of repeatedly loading and
   *     storing B[r][s].
   *
   *   - We exploit symmetry: B[r][s] == B[s][r]. For each pair (r, s) with
   *     s <= r, we compute the inner product once and then write both
   *     B[r][s] and B[s][r]. This halves the number of inner products.
   *
   *   - The previous explicit zero-initialization of B is no longer needed,
   *     because every B[r][s] is fully written exactly once before being
   *     read.
   *
   *   - The outer loop over r is parallelized with OpenMP. Each (r, s) pair
   *     is computed by exactly one iteration (no overlapping writes), so
   *     there are no data races.
   */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Compute B = A * A^T, exploiting symmetry. */
  #pragma omp parallel for private(s, t) schedule(static)
  for (r = 0; r < n; ++r)
    {
      for (s = 0; s <= r; ++s)
        {
          DATA_TYPE sum = (DATA_TYPE)0.0;

          for (t = 0; t < n; ++t)
            sum += A[r][t] * A[s][t];

          (POLYBENCH_ARRAY(B))[r][s] = sum;

          /* Mirror the symmetric element to avoid recomputing it. */
          if (s != r)
            (POLYBENCH_ARRAY(B))[s][r] = sum;
        }
    }

  /* Copy B back into A. Using memcpy encourages the compiler to generate
   * efficient bulk memory moves and is equivalent to the original element-wise
   * copy.
   */
  for (r = 0; r < n; ++r)
    memcpy(A[r],
           (POLYBENCH_ARRAY(B))[r],
           (size_t)n * sizeof(DATA_TYPE));

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 *  - Introduce a row pointer Ai for A[i] to improve cache locality and
 *    reduce address computation.
 *  - For the lower-triangular (L) part, accumulate into a scalar temporary
 *    'tmp' instead of repeatedly updating A[i][j] in memory. This preserves
 *    the original evaluation order for the inner-product while keeping the
 *    accumulator in a register.
 *  - For the upper-triangular (U) part, interchange the j and k loops:
 *      original: for j in [i, N) { for k in [0, i) { ... } }
 *      new:      for k in [0, i) { for j in [i, N) { ... } }
 *    For each fixed (i, j), the sequence of updates over k remains in the
 *    same order (k = 0, 1, ..., i-1), so the computed value of A[i][j] is
 *    identical to the original. This transformation greatly improves cache
 *    reuse: A[i][k] is loaded once per k and reused across all j, and
 *    A[k][j] is accessed contiguously along the row.
 *  - Annotate the innermost j-loop in the U update with '#pragma omp simd'
 *    to encourage vectorization when OpenMP SIMD is enabled. The iterations
 *    over j are independent, so reordering them is safe.
 *
 *  Dependencies:
 *   - The outer loop over i remains strictly sequential, as each row i
 *     depends on previously computed rows 0..i-1.
 */
static
void kernel_lu[[gnu::flatten, gnu::noinline]](int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    /* Cached pointer to the current row of A. */
    DATA_TYPE *Ai = A[i];

    /* Compute the L factors (below the diagonal) for row i. This loop is kept
     * in essentially the same order as the original to preserve dependence
     * structure and numerical behavior.
     *
     * Original:
     *   for (j = 0; j < i; j++) {
     *     for (k = 0; k < j; k++)
     *       A[i][j] -= A[i][k] * A[k][j];
     *     A[i][j] /= A[j][j];
     *   }
     *
     * New:
     *   - Use a scalar accumulator 'tmp' instead of updating Ai[j] in memory
     *     at each inner iteration.
     */
    for (j = 0; j < i; j++) {
      DATA_TYPE tmp = Ai[j];

      for (k = 0; k < j; k++) {
        tmp -= Ai[k] * A[k][j];
      }

      tmp /= A[j][j];
      Ai[j] = tmp;
    }

    /* Compute the U factors (on and above the diagonal) for row i.
     *
     * Original:
     *   for (j = i; j < _PB_N; j++) {
     *     for (k = 0; k < i; k++)
     *       A[i][j] -= A[i][k] * A[k][j];
     *   }
     *
     * Transformed:
     *   for (k = 0; k < i; k++) {
     *     Aik = A[i][k];
     *     for (j = i; j < _PB_N; j++)
     *       A[i][j] -= Aik * A[k][j];
     *   }
     *
     * For any fixed (i, j), both versions perform the updates over k in the
     * order k = 0, 1, ..., i-1. The difference is only in how the operations
     * for different j are interleaved, which does not affect the final value
     * because there are no dependencies between different columns j in this
     * phase.
     */
    for (k = 0; k < i; k++) {
      const DATA_TYPE Aik = Ai[k];
      const DATA_TYPE *Ak = A[k];

      /* The updates across j are independent for a fixed (i, k). This makes
       * the loop a good candidate for SIMD vectorization.
       */
      #pragma omp simd
      for (j = i; j < _PB_N; j++) {
        Ai[j] -= Aik * Ak[j];
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_lu (n, POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
