/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

  /* Initialize A as a unit-lower plus upper matrix. */
  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++) {
	A[i][j] = 0;
      }
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite.
     Not necessary for LU, but we keep the same behavior as in
     the original code (used also by the Cholesky benchmark). */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  DATA_TYPE (*B_arr)[n] = POLYBENCH_ARRAY(B);

  /* Compute B = A * A^T with a cache-friendly loop nest.
     For each (r,s) pair, we accumulate over t in strictly
     increasing order, exactly as in the original (t,r,s) loop,
     so floating-point semantics are preserved. */
  for (r = 0; r < n; ++r) {
    for (s = 0; s < n; ++s) {
      DATA_TYPE sum = (DATA_TYPE)0;
      for (t = 0; t < n; ++t) {
        sum += A[r][t] * A[s][t];
      }
      B_arr[r][s] = sum;
    }
  }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      A[r][s] = B_arr[r][s];

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
