    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_lu[[gnu::flatten, gnu::noinline]](int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

  /* Use the PolyBench "effective" problem size.
     Keeping it in a local variable may help the optimizer. */
  const int nPB = _PB_N;

#pragma scop
  for (i = 0; i < nPB; i++) {
    /* Cache the current row pointer to improve spatial locality and
       avoid recomputing A[i] repeatedly. The 'restrict' qualifier
       documents that this pointer is the only one used to access
       row i in this scope. */
    DATA_TYPE *restrict Ai = A[i];

    /* Compute the L-factor entries in row i: columns j = 0 .. i-1. */
    for (j = 0; j < i; j++) {
      /* Keep the running value in a scalar to avoid repeated
         loads/stores through A[i][j]. This preserves the exact
         arithmetic sequence of the original loop. */
      DATA_TYPE sum = Ai[j];

      for (k = 0; k < j; k++) {
        sum -= Ai[k] * A[k][j];
      }

      /* Finalize L(i,j). */
      Ai[j] = sum / A[j][j];
    }

    /* Compute the U-factor entries in row i: columns j = i .. nPB-1.
       Original form (per element j):
         for k = 0 .. i-1:
           A[i][j] -= A[i][k] * A[k][j];

       We transform this into an outer-product style update:

         for k = 0 .. i-1:
           for j = i .. nPB-1:
             A[i][j] -= A[i][k] * A[k][j];

       For each fixed (i,j), the updates over k still occur in
       increasing-k order, so the numerical result per element is
       identical. This reordering greatly improves cache reuse of
       row k (A[k][j]) and enables better vectorization. */
    for (k = 0; k < i; k++) {
      const DATA_TYPE Aik = Ai[k];
      const DATA_TYPE *restrict Ak = A[k];

      /* Each iteration updates a distinct A[i][j] and reads only
         Aik and Ak[j], so iterations are independent and can be
         safely vectorized. When compiled without OpenMP support
         this pragma is ignored by the compiler. */
#pragma omp simd
      for (j = i; j < nPB; j++) {
        Ai[j] -= Aik * Ak[j];
      }
    }
  }
#pragma endscop
}


